CREATE TABLE `app_sessions` (
  `sid` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `data` mediumtext NOT NULL,
  `expires` bigint NOT NULL,
  PRIMARY KEY (`sid`),
  KEY `ix_sessions_expires` (`expires`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `attractions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(1024) DEFAULT NULL,
  `description` varchar(1024) DEFAULT NULL,
  `location` varchar(1024) DEFAULT NULL,
  `significant_features` varchar(1024) DEFAULT NULL,
  `activities` json DEFAULT NULL,
  `img1` varchar(1024) DEFAULT NULL,
  `img2` varchar(1024) DEFAULT NULL,
  `img3` varchar(1024) DEFAULT NULL,
  `img4` varchar(1024) DEFAULT NULL,
  `province` varchar(255) DEFAULT NULL,
  `opening_hours` varchar(255) DEFAULT NULL,
  `phone` varchar(64) DEFAULT NULL,
  `site` varchar(1024) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (1, 'Victoria Falls', 'Victoria Falls, one of the Seven Natural Wonders of the World, is a magnificent waterfall located on the Zambezi River, straddling the border between Zambia and Zimbabwe. Known locally as \'Mosi-oa-Tunya\' or \'The Smoke That Thunders\', this UNESCO World Heritage Site features a dramatic curtain of water that cascades over 100 meters high and more than 1,700 meters wide. The falls are surrounded by lush rainforests and offer breathtaking views, particularly during the peak rainy season when the flow is at its highest.', 'Livingstone, Southern Province', 'Largest sheet of falling water in the world, Rainforest ecosystem, Numerous viewpoints and bridges', '[\"Bungee Jumping\",\"White Water Rafting\",\"Helicopter Tours\",\"Sunset Cruises\",\"Walking Tours\"]', 'images/attractions/victoriafalls/1.jpg', 'images/attractions/victoriafalls/2.jpg', 'images/attractions/victoriafalls/3.jpg', 'images/attractions/victoriafalls/4.jpg', 'Southern', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (2, 'Lower Zambezi National Park', 'Lower Zambezi National Park is a stunning wildlife reserve located in the southeastern part of Zambia. The park is situated along the Zambezi River and is renowned for its rich biodiversity, including elephants, lions, hippos, and numerous bird species. The landscape features a mix of floodplains, woodlands, and riverine forests, providing varied habitats for wildlife. The park offers excellent opportunities for game viewing, fishing, and boat safaris, making it a haven for nature enthusiasts and adventure seekers alike.', 'Southeastern Zambia', 'Diverse wildlife, Scenic river views, Great fishing opportunities', '[\"Game Drives\",\"Boat Safaris\",\"Fishing\",\"Walking Safaris\",\"Dancing\"]', 'images/attractions/lowerzambezinationalpark/1.jpg', 'images/attractions/lowerzambezinationalpark/2.jpg', 'images/attractions/lowerzambezinationalpark/3.jpg', 'images/attractions/lowerzambezinationalpark/4.jpg', NULL, NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (3, 'South Luangwa National Park', 'South Luangwa National Park is one of Zambia\'s premier wildlife destinations, located in the eastern part of the country. The park is famous for its incredible wildlife viewing opportunities, with large populations of elephants, leopards, lions, and buffaloes. The Luangwa River, which runs through the park, creates lush floodplains and numerous waterholes that attract wildlife, making it an ideal location for game drives and walking safaris. South Luangwa also features several walking safari camps, offering an immersive wilderness experience.', 'Eastern Zambia', 'Exceptional wildlife density, Walking safaris, Luangwa River', '[\"Game Drives\",\"Walking Safaris\",\"Night Safaris\",\"Bird Watching\",\"Photography\"]', 'images/attractions/southluangwanationalpark/1.jpg', 'images/attractions/southluangwanationalpark/2.jpg', 'images/attractions/southluangwanationalpark/3.jpg', 'images/attractions/southluangwanationalpark/4.jpg', 'Eastern', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (4, 'Kafue National Park', 'Kafue National Park is Zambia\'s largest national park, located in the central-western part of the country. The park is known for its vast landscapes, which include savannahs, wetlands, and river systems. Kafue is home to a diverse array of wildlife, including leopards, cheetahs, elephants, and a variety of antelope species. The park\'s key features include the Kafue River and the Busanga Plains, which offer excellent game viewing and bird watching opportunities.', 'Central-Western Zambia', 'Vast landscapes, Busanga Plains, Kafue River', '[\"Game Drives\",\"Boat Safaris\",\"Walking Safaris\",\"Bird Watching\",\"Fishing\"]', 'images/attractions/kafuenationalpark/1.jpg', 'images/attractions/kafuenationalpark/2.jpg', 'images/attractions/kafuenationalpark/3.jpg', 'images/attractions/kafuenationalpark/4.jpg', 'Central, Western', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (5, 'Luambe National Park', 'Luambe National Park is a lesser-known gem located in the northern part of Zambia, along the Luangwa River. The park is characterized by its pristine wilderness and low visitor numbers, offering an off-the-beaten-path safari experience. Luambe is home to a range of wildlife, including elephants, leopards, and various antelope species. The park\'s remote location makes it a perfect destination for those seeking solitude and a true sense of adventure.', 'Northern Zambia', 'Remote wilderness, Low visitor numbers, Luangwa River', '[\"Game Drives\",\"Walking Safaris\",\"Bird Watching\",\"Fishing\",\"Photography\"]', 'images/attractions/luambenationalpark/1.jpg', 'images/attractions/luambenationalpark/2.jpg', 'images/attractions/luambenationalpark/3.jpg', 'images/attractions/luambenationalpark/4.jpg', 'Northern', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (6, 'Livingstone Museum', 'The Livingstone Museum, located in the town of Livingstone, is Zambia\'s largest and oldest museum. It offers an extensive collection of artifacts and exhibits related to the country\'s history, culture, and natural heritage. Highlights include displays on the life of explorer David Livingstone, prehistoric fossils, and traditional Zambian crafts. The museum provides valuable insights into Zambia\'s past and is a must-visit for history enthusiasts and those interested in Zambian culture.', 'Livingstone, Southern Province', 'David Livingstone exhibits, Prehistoric fossils, Traditional crafts', '[\"Museum Tours\",\"Cultural Exhibits\",\"Educational Programs\",\"Historical Exhibits\",\"Photography\"]', 'images/attractions/livingstonemuseum/1.jpg', 'images/attractions/livingstonemuseum/2.jpg', 'images/attractions/livingstonemuseum/3.jpg', 'images/attractions/livingstonemuseum/4.jpg', 'Southern', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (7, 'Zambezi National Park', 'Zambezi National Park, located in the western part of Zambia, is known for its stunning landscapes along the Zambezi River. The park is rich in wildlife, including elephants, hippos, and a variety of antelope species. Visitors can enjoy boat safaris along the river, which offer unique opportunities to see animals up close in their natural habitat. The park is also home to several scenic spots, including the impressive Zambezi River gorge.', 'Western Zambia', 'Zambezi River, Diverse wildlife, Scenic river views', '[\"Boat Safaris\",\"Game Drives\",\"Fishing\",\"Bird Watching\",\"Scenic Photography\"]', 'images/attractions/zambezinationapark/1.jpg', 'images/attractions/zambezinationapark/2.jpg', 'images/attractions/zambezinationapark/3.jpg', 'images/attractions/zambezinationapark/4.jpg', 'Western', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (8, 'Kalambo Falls', 'Kalambo Falls, located on the Kalambo River in northern Zambia, is one of the highest uninterrupted waterfalls in Africa. The falls drop nearly 221 meters into a deep gorge, creating a spectacular sight surrounded by lush vegetation. The area around Kalambo Falls is relatively remote, offering visitors a chance to experience Zambia\'s natural beauty and tranquility away from the more frequented tourist spots.', 'Northern Zambia', 'High uninterrupted drop, Remote location, Scenic views', '[\"Hiking\",\"Photography\",\"Nature Walks\",\"Picnicking\",\"Exploring\"]', 'images/attractions/kalambofalls/1.jpg', 'images/attractions/kalambofalls/2.jpg', 'images/attractions/kalambofalls/3.jpg', 'images/attractions/kalambofalls/4.jpg', 'Northern', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (9, 'Nyika Plateau', 'Nyika Plateau is a high-altitude plateau located in the northern part of Zambia, bordering Malawi. The area is known for its unique landscape of rolling grasslands, montane forests, and rich biodiversity. Nyika Plateau is home to a variety of wildlife, including zebra, antelope, and several species of birds. The plateau\'s cool climate and stunning scenery make it an ideal destination for trekking and wildlife viewing.', 'Northern Zambia', 'High-altitude grasslands, Diverse wildlife, Stunning scenery', '[\"Trekking\",\"Wildlife Viewing\",\"Bird Watching\",\"Photography\",\"Camping\"]', 'images/attractions/Nyikaplateau/1.jpg', 'images/attractions/Nyikaplateau/2.jpg', 'images/attractions/Nyikaplateau/3.jpg', 'images/attractions/Nyikaplateau/4.jpg', 'Northern', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (10, 'Mosi-oa-Tunya National Park', 'Mosi-oa-Tunya National Park, located near Livingstone, is named after the famous Victoria Falls, also known as Mosi-oa-Tunya. The park features a variety of habitats including riverine forests, savannahs, and wetlands. It is home to a range of wildlife, such as elephants, buffaloes, and white rhinos. The park offers scenic views of the falls and opportunities for game viewing and nature walks.', 'Near Livingstone', 'Proximity to Victoria Falls, Rich wildlife, Scenic river views', '[\"Game Drives\",\"Nature Walks\",\"Picnicking\",\"Bird Watching\",\"Photography\"]', 'images/attractions/mosi/1.jpg', 'images/attractions/mosi/2.jpg', 'images/attractions/mosi/3.jpg', 'images/attractions/mosi/4.jpg', NULL, NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (11, 'Liuwa Plain National Park', 'Liuwa Plain National Park is located in western Zambia and is known for its vast, open plains and seasonal wildlife migrations. The park is home to large herds of wildebeest, zebra, and other antelope species. Liuwa Plain is one of the least visited parks in Zambia, offering a remote and authentic safari experience. The park also features the Liuwa River and seasonal floodplains, providing vital habitats for the wildlife.', 'Western Zambia', 'Seasonal wildlife migrations, Vast plains, Liuwa River', '[\"Game Drives\",\"Bird Watching\",\"Photography\",\"Camping\",\"Exploring Floodplains\"]', 'images/attractions/liuwa/1.jpg', 'images/attractions/liuwa/2.jpg', 'images/attractions/liuwa/3.jpg', 'images/attractions/liuwa/4.jpg', 'Western', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (12, 'Kafue River', 'The Kafue River is a major river in Zambia, flowing through Kafue National Park and offering diverse opportunities for wildlife viewing and water-based activities. The river is crucial for the park\'s ecosystem, supporting a wide range of wildlife, including hippos and crocodiles. Visitors can enjoy boat safaris along the river, providing unique perspectives of the wildlife and stunning scenery. The river\'s meandering course creates various habitats that are home to numerous bird and animal species.', 'Central Zambia', 'Major river, Boat safaris, Diverse wildlife habitats', '[\"Boat Safaris\",\"Fishing\",\"Bird Watching\",\"Photography\",\"River Cruises\"]', 'images/attractions/kafueriver/1.jpg', 'images/attractions/kafueriver/2.jpg', 'images/attractions/kafueriver/3.jpg', 'images/attractions/kafueriver/4.jpg', 'Central', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (13, 'Kasanka National Park', 'Kasanka National Park, located in northern Zambia, is known for its seasonal bat migration, one of the largest mammal migrations in the world. The park features diverse habitats, including swamps, forests, and grasslands, which support a variety of wildlife such as antelopes, elephants, and numerous bird species. The bat migration, which occurs from October to December, is a highlight for visitors, offering a spectacular view of millions of fruit bats taking to the skies at dusk.', 'Northern Zambia', 'Seasonal bat migration, Diverse habitats, Rich birdlife', '[\"Bat Viewing\",\"Game Drives\",\"Bird Watching\",\"Nature Walks\",\"Photography\"]', 'images/attractions/kasankanationalpark/1.jpg', 'images/attractions/kasankanationalpark/2.jpg', 'images/attractions/kasankanationalpark/3.jpg', 'images/attractions/kasankanationalpark/4.jpg', 'Northern', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (14, 'Chirundu', 'Chirundu, located on the banks of the Zambezi River in northern Zambia, is a popular spot for fishing and relaxation. The town serves as a gateway to Lower Zambezi National Park and offers excellent opportunities for fishing and boating. The Zambezi River is known for its abundant fish species, including tiger fish, which attract anglers from around the world. Chirundu\'s scenic river views and tranquil environment make it a great destination for outdoor enthusiasts.', 'Northern Zambia', 'Zambezi River fishing, Scenic views, Proximity to Lower Zambezi National Park', '[\"Fishing\",\"Boat Tours\",\"Wildlife Viewing\",\"Relaxation\",\"Photography\"]', 'images/attractions/chirundu/1.jpg', 'images/attractions/chirundu/2.jpg', 'images/attractions/chirundu/3.jpg', 'images/attractions/chirundu/4.jpg', 'Northern', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (15, 'Lumangwe Falls', 'Lumangwe Falls, located in the Northern Province of Zambia, is a beautiful and relatively undiscovered waterfall. The falls cascade down a rugged gorge, creating a dramatic and scenic setting. The surrounding area is lush and verdant, providing a picturesque backdrop for visitors. Lumangwe Falls is a great destination for those looking to explore Zambia\'s natural beauty and enjoy a peaceful, off-the-beaten-path experience.', 'Northern Province, Zambia', 'Scenic waterfall, Rugged gorge, Lush surroundings', '[\"Hiking\",\"Photography\",\"Picnicking\",\"Nature Exploration\",\"Relaxation\"]', 'images/attractions/lumangwe/1.jpg', 'images/attractions/lumangwe/2.jpg', 'images/attractions/lumangwe/3.jpg', 'images/attractions/lumangwe/4.jpg', 'Northern', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (16, 'Chirundu Rock Art', 'Chirundu Rock Art, located near the town of Chirundu, features ancient rock engravings created by early inhabitants of the region. The rock art provides valuable insights into the prehistoric cultures that once lived in the area. The engravings depict various animals and human figures, offering a glimpse into the artistic and cultural practices of early Zambians. The site is a fascinating destination for history and archaeology enthusiasts.', 'Near Chirundu, Zambia', 'Ancient rock engravings, Prehistoric art, Cultural insights', '[\"Rock Art Viewing\",\"Cultural Tours\",\"Photography\",\"Historical Exploration\",\"Educational Visits\"]', 'images/attractions/rockart/1.jpg', 'images/attractions/rockart/2.jpg', 'images/attractions/rockart/3.jpg', 'images/attractions/rockart/4.jpg', NULL, NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (17, 'Lake Kariba', 'Lake Kariba, one of the world\'s largest artificial lakes, is situated on the border between Zambia and Zimbabwe. The lake is known for its stunning scenery, with its vast expanse of water set against a backdrop of rugged hills and forests. Lake Kariba offers a range of recreational activities, including boat safaris, fishing, and camping. The lake\'s rich wildlife and scenic beauty make it a popular destination for outdoor enthusiasts.', 'Border of Zambia and Zimbabwe', 'Large artificial lake, Scenic landscapes, Recreational activities', '[\"Boat Safaris\",\"Fishing\",\"Camping\",\"Wildlife Viewing\",\"Water Sports\"]', 'images/attractions/lakekariba/1.jpg', 'images/attractions/lakekariba/2.jpg', 'images/attractions/lakekariba/3.jpg', 'images/attractions/lakekariba/4.jpg', NULL, NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (18, 'Sumbu National Park', 'Sumbu National Park, located on the shores of Lake Tanganyika, is a remote and pristine park known for its beautiful landscapes and diverse wildlife. The park features a variety of habitats, including forests, savannahs, and lakeshore areas. Sumbu is home to several species of mammals, birds, and fish, and offers excellent opportunities for game viewing and bird watching. The park\'s lakeside setting and rich biodiversity make it a unique destination for nature lovers.', 'Northern Zambia, Lake Tanganyika', 'Lakeside setting, Diverse wildlife, Remote and pristine', '[\"Game Drives\",\"Bird Watching\",\"Fishing\",\"Nature Walks\",\"Photography\"]', 'images/attractions/sumbu/1.jpg', 'images/attractions/sumbu/2.jpg', 'images/attractions/sumbu/3.jpg', 'images/attractions/sumbu/4.jpg', 'Northern', NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (19, 'Mukuni Village', 'Mukuni Village, located near Livingstone, is a traditional village that offers visitors a glimpse into the culture and lifestyle of the local Leya people. The village features traditional huts, crafts, and cultural performances, providing an immersive cultural experience. Visitors can learn about traditional customs, participate in local ceremonies, and enjoy authentic Zambian cuisine. Mukuni Village is a great destination for those interested in cultural tourism and community interactions.', 'Near Livingstone', 'Traditional village life, Cultural performances, Authentic Zambian cuisine', '[\"Village Tours\",\"Cultural Performances\",\"Craft Workshops\",\"Traditional Cooking\",\"Photography\"]', 'images/attractions/mukuni/1.jpg', 'images/attractions/mukuni/2.jpg', 'images/attractions/mukuni/3.jpg', 'images/attractions/mukuni/4.jpg', NULL, NULL, NULL, NULL);
INSERT INTO `attractions` (`id`, `name`, `description`, `location`, `significant_features`, `activities`, `img1`, `img2`, `img3`, `img4`, `province`, `opening_hours`, `phone`, `site`) VALUES (20, 'Sioma Ngwezi National Park', 'Sioma Ngwezi National Park, located in southwestern Zambia, is known for its remote wilderness and rich wildlife. The park features a diverse landscape of grasslands, woodlands, and river systems. Sioma Ngwezi is home to a variety of wildlife, including elephants, lions, and several antelope species. The park\'s isolation and limited tourism infrastructure make it an ideal destination for those seeking an adventurous and off-the-beaten-path safari experience.', 'Southwestern Zambia', 'Remote wilderness, Diverse wildlife, Varied landscapes', '[\"Game Drives\",\"Walking Safaris\",\"Bird Watching\",\"Photography\",\"Exploration\"]', 'images/attractions/sioma/1.jpg', 'images/attractions/sioma/2.jpg', 'images/attractions/sioma/3.jpg', 'images/attractions/sioma/4.jpg', NULL, NULL, NULL, NULL);

CREATE TABLE `chillspots` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `ln` varchar(1024) DEFAULT NULL,
  `img` varchar(1024) DEFAULT NULL,
  `h1` varchar(1024) DEFAULT NULL,
  `h2` varchar(1024) DEFAULT NULL,
  `p` varchar(1024) DEFAULT NULL,
  `details` mediumtext,
  `img1` varchar(1024) DEFAULT NULL,
  `img2` varchar(1024) DEFAULT NULL,
  `img3` varchar(1024) DEFAULT NULL,
  `img4` varchar(1024) DEFAULT NULL,
  `map` varchar(1024) DEFAULT NULL,
  `phone` varchar(1024) DEFAULT NULL,
  `address` varchar(1024) DEFAULT NULL,
  `site` varchar(1024) DEFAULT NULL,
  `opening_hours` varchar(255) DEFAULT NULL,
  `activities` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (1, 'lsk', 'images/sites/Lusaka/37DGallery/1.jpg', '37D', 'Art Gallery', '37D Gallery in Lusaka showcases contemporary Zambian and African art, promoting local artists and cultural enrichment.', '37D Gallery, located in Lusaka, Zambia, is a vibrant hub for contemporary African art, offering a unique space where creativity and culture converge. The gallery is renowned for its commitment to showcasing the works of both emerging and established Zambian and African artists, making it a crucial platform for the promotion of local talent and the preservation of cultural heritage. Visitors to 37D Gallery are treated to a diverse collection of art that spans various mediums, including painting, sculpture, photography, and mixed media. The gallery’s exhibitions are carefully curated to reflect the rich tapestry of African life, exploring themes that range from traditional African narratives to modern-day issues, thus providing a thought-provoking experience for art lovers and collectors alike. The serene and welcoming atmosphere of 37D Gallery allows visitors to fully immerse themselves in the artworks, encouraging a deeper connection and understanding of the stories and emotions conveyed through the pieces. In addition to its exhibitions, 37D Gallery also hosts a variety of events, such as artist talks, workshops, and cultural exchanges, further establishing it as a dynamic space for artistic dialogue and community engagement. Whether you are a seasoned art enthusiast or a curious newcomer, 37D Gallery offers a rich and inspiring journey into the heart of African art, making it a must-visit destination in Lusaka for anyone interested in the vibrant and evolving landscape of contemporary African creativity.', 'images/sites/Lusaka/37DGallery/2.jpg', 'images/sites/Lusaka/37DGallery/3.jpg', 'images/sites/Lusaka/37DGallery/4.jpg', 'images/sites/Lusaka/37DGallery/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3845.9928328680903!2d28.35024877512263!3d-15.430938185159837!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19408c5f03b581fd%3A0x9075a2ae8c008254!2s37d%20Gallery!5e0!3m2!1sen!2szm!4v1724032475727!5m2!1sen!2szm', '0973006919', '37 D, Middleway, Lusaka', 'https://37dGallery.com', NULL, '[\"Art & culture\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (2, 'lsk', 'images/sites/Lusaka/CrossPark/1.jpg', 'Cross Park', 'Leisure Park', 'Cross Park in Lusaka is a popular destination for relaxation, offering a blend of green spaces, walking trails, and recreational activities for families and visitors.', 'Cross Park in Lusaka is a favorite spot for both locals and tourists seeking a peaceful escape within the city. The park features expansive green lawns, well-maintained walking paths, and designated areas for picnics and outdoor activities. It is an ideal location for family outings, providing playgrounds for children, shaded seating areas, and ample space for sports and recreation. The park also hosts occasional events such as outdoor concerts and community gatherings, enhancing its role as a social and cultural hub in Lusaka. Cross Park’s serene environment, combined with its accessibility and amenities, makes it a perfect place to unwind, enjoy nature, and spend quality time with loved ones.', 'images/sites/Lusaka/CrossPark/2.jpg', 'images/sites/Lusaka/CrossPark/3.jpg', 'images/sites/Lusaka/CrossPark/4.jpg', 'images/sites/Lusaka/CrossPark/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d30759.173384764603!2d28.452502050000003!3d-15.489989099999995!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x194091501ac0bd83%3A0xab121f2021df1b6f!2sThe%20Cross%20park!5e0!3m2!1sen!2szm!4v1724050640798!5m2!1sen!2szm', '0973006920', 'Lusaka, Zambia', 'https://www.crossparklusaka.com', NULL, '[\"Outdoor recreation\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (3, 'lsk', 'images/sites/Lusaka/LowerZambeziNationalPark/1.jpg', 'Lower Zambezi', 'National Park', 'Lower Zambezi National Park is a pristine wilderness area in Zambia, known for its rich wildlife, stunning landscapes, and opportunities for canoeing and fishing on the Zambezi River.', 'Lower Zambezi National Park is one of Zambia\'s premier safari destinations, offering visitors an unparalleled experience of the African wilderness. Situated along the banks of the mighty Zambezi River, the park is home to a diverse range of wildlife, including elephants, lions, leopards, hippos, and numerous bird species. The park\'s unique geography, with its riverine forests, floodplains, and escarpments, provides a stunning backdrop for game viewing, whether on a traditional safari drive, a guided walking tour, or a canoeing excursion on the river. Canoeing along the Zambezi allows for close encounters with hippos, crocodiles, and a variety of birdlife, making it one of the most memorable ways to experience the park. The Lower Zambezi National Park is also renowned for its excellent fishing opportunities, particularly for tigerfish, which attract anglers from around the world. The park\'s remote location and limited number of lodges ensure an exclusive and intimate experience, far from the crowds, allowing visitors to truly connect with nature in its purest form.', 'images/sites/Lusaka/LowerZambeziNationalPark/2.jpg', 'images/sites/Lusaka/LowerZambeziNationalPark/3.jpg', 'images/sites/Lusaka/LowerZambeziNationalPark/4.jpg', 'images/sites/Lusaka/LowerZambeziNationalPark/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3848.183187429608!2d29.6035495!3d-15.312276700000002!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x193eeb70788bd2ad%3A0xa4f2d72197775f7!2sLower%20Zambezi%20National%20Park!5e0!3m2!1sen!2szm!4v1724050700918!5m2!1sen!2szm', '0973006930', 'Lower Zambezi, Lusaka Province, Zambia', 'https://www.lowerzambezi.com', NULL, '[\"Wildlife\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (4, 'lsk', 'images/sites/Lusaka/LusakaNationalPark/1.jpg', 'Lusaka', 'National Park', 'Lusaka National Park offers a unique wildlife experience close to the city, featuring a variety of animals including giraffes, zebras, and white rhinos, ideal for a quick nature escape.', 'Lusaka National Park, located just a short drive from the city center, is the newest addition to Zambia\'s national parks and offers an easily accessible wildlife experience for both residents and visitors. Despite its proximity to the urban area, the park provides a tranquil escape into nature, with over 20 species of animals, including giraffes, zebras, wildebeests, and the endangered white rhino. The park is ideal for a half-day or full-day excursion, offering self-drive and guided game drives along well-maintained tracks. In addition to game viewing, visitors can enjoy picnicking in designated areas, bird watching, and hiking along marked trails. The park’s management has also implemented conservation programs aimed at protecting the white rhino population, making it not only a recreational site but also a place of significant environmental importance. Lusaka National Park is a perfect destination for those looking to experience Zambia\'s wildlife without having to travel far from the capital.', 'images/sites/Lusaka/LusakaNationalPark/2.jpg', 'images/sites/Lusaka/LusakaNationalPark/3.jpg', 'images/sites/Lusaka/LusakaNationalPark/4.jpg', 'images/sites/Lusaka/LusakaNationalPark/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d984150.0834065874!2d27.864410165625!3d-15.520094099999989!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x194091a706080d15%3A0x90c20e097a960fdf!2sLusaka%20National%20Park!5e0!3m2!1sen!2szm!4v1724050911169!5m2!1sen!2szm', '0973006940', 'Lusaka National Park, Lusaka, Zambia', '', NULL, '[\"Wildlife\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (5, 'lsk', 'images/sites/Lusaka/Mukamunyaclubandmonkeypools/1.jpg', 'Mukanya Club', '& Monkey Pool', 'Mukanya Club is a vibrant social venue in Lusaka, known for its lively atmosphere, music, and events, making it a favorite spot for nightlife and entertainment.', 'Mukanya Club and Monkey Pool, located in Lusaka, is a hotspot for nightlife and social gatherings. The venue offers a lively and dynamic atmosphere, with regular events, live music performances, and DJ nights that draw a diverse crowd. The Monkey Pool, a unique feature of the club, adds to the fun and relaxed vibe, making it a popular spot for both locals and visitors looking to unwind and have a good time. The club\'s menu includes a variety of beverages and snacks, catering to different tastes, and the friendly staff ensures that everyone has a great experience. Whether you\'re looking to dance the night away, enjoy some good music, or simply hang out with friends, Mukanya Club is the place to be.', 'images/sites/Lusaka/Mukamunyaclubandmonkeypools/2.jpg', 'images/sites/Lusaka/Mukamunyaclubandmonkeypools/3.jpg', 'images/sites/Lusaka/Mukamunyaclubandmonkeypools/4.jpg', 'images/sites/Lusaka/Mukamunyaclubandmonkeypools/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1968823.372020051!2d27.330181131249997!3d-15.465155899999989!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19408fcffcf5a3e1%3A0x3f6a75f03fcf07c4!2sMukaMunya%20Residents%20Clubhouse!5e0!3m2!1sen!2szm!4v1724051014024!5m2!1sen!2szm', '0973006950', 'Mukanya Club, Lusaka, Zambia', '', NULL, '[\"Swimming\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (6, 'cb', 'images/sites/cb/athiti/1.jpg', 'ATHITITS', 'Garden Restaurant & Bar', 'Step into a tranquil oasis at our Garden Restaurant and Bar! Enjoy delicious cuisine and refreshing drinks surrounded by lush greenery.', 'ATHITITS Garden Restaurant & Bar is a hidden gem located in the Copperbelt region, offering a serene escape from the hustle and bustle of city life. Nestled within lush gardens, this venue provides a peaceful ambiance where guests can enjoy a meal or a drink in a natural setting. The menu features a variety of local and international dishes, all prepared with fresh ingredients and served with a touch of elegance. The bar offers a wide selection of beverages, from classic cocktails to locally brewed beers, making it an ideal spot for a relaxed afternoon or a casual evening out. The restaurant also hosts special events, such as live music nights and themed dinners, adding to the overall charm of the place. Whether you\'re looking for a quiet lunch, a romantic dinner, or a social gathering with friends, ATHITITS Garden Restaurant & Bar promises a delightful experience.', 'images/sites/cb/athiti/2.jpg', 'images/sites/cb/athiti/3.jpg', 'images/sites/cb/athiti/4.jpg', 'images/sites/cb/athiti/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3890.5425474345284!2d28.2252911!3d-12.8081783!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x196ce70145e17839%3A0x4295cd65917087e2!2sATITHI%20MULTICUISINE%20GARDEN%20RESTAURANT%20%26%20BAR!5e0!3m2!1sen!2szm!4v1724051054376!5m2!1sen!2szm', '0973006960', 'Chiwala Avenue Parklands Kitwe ZM, 50100', '', NULL, '[\"Dining\",\"Drinks\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (7, 'cb', 'images/sites/cb/bojangos/1.jpg', 'BO\'JANGLES', 'Pub, Grill & Pizzeria', 'Bojangos offers a relaxed atmosphere with a variety of hearty meals and refreshing beverages. Ideal for a laid-back meal with friends or family.', 'BO\'JANGLES Pub, Grill & Pizzeria is a lively and welcoming spot in the Copperbelt, known for its friendly atmosphere and great food. The menu includes a variety of options, from juicy burgers and sizzling steaks to freshly made pizzas and hearty pasta dishes, ensuring there\'s something for everyone. The pub area features a well-stocked bar with a wide selection of drinks, including local brews, international beers, and classic cocktails. BO\'JANGLES is a popular choice for casual dining with friends, family gatherings, or even a fun night out, thanks to its warm, inviting setting and excellent service. The venue also hosts regular events such as quiz nights, karaoke, and live music, making it a central hub for entertainment in the area.', 'images/sites/cb/bojangos/2.jpg', 'images/sites/cb/bojangos/3.jpg', 'images/sites/cb/bojangos/4.jpg', 'images/sites/cb/bojangos/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3887.848650091619!2d28.639927699999994!3d-12.981530499999998!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x196cb4ef8a235ab1%3A0xda2467b9b31d0f88!2sBo&#39;Jangles%20Pub%20Grill%20%26%20Pizzeria!5e0!3m2!1sen!2szm!4v1724051151616!5m2!1sen!2szm', '0973006970', 'Kafubu Mall, Ndola', '', NULL, '[\"Dining\",\"Drinks\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (8, 'cb', 'images/sites/cb/honeydew/1.jpg', 'HONEYDEW', 'Restaurant', 'Honeydew Restaurant provides a sophisticated dining experience with gourmet dishes and exceptional service, perfect for special occasions and elegant meals.', 'Honeydew Restaurant, located in the heart of the Copperbelt, offers a refined dining experience that blends gourmet cuisine with an elegant setting. The restaurant\'s menu features a wide range of dishes, from locally inspired creations to international favorites, all made with the finest ingredients. The ambiance is both sophisticated and welcoming, making it an ideal choice for special occasions, business dinners, or a romantic night out. Honeydew\'s exceptional service and attention to detail ensure that every meal is a memorable one. In addition to its regular menu, the restaurant also offers a selection of fine wines and handcrafted cocktails, perfectly complementing the culinary delights on offer.', 'images/sites/cb/honeydew/2.jpg', 'images/sites/cb/honeydew/3.jpg', 'images/sites/cb/honeydew/4.jpg', 'images/sites/cb/honeydew/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3890.657670733257!2d28.2271028!3d-12.8007187!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x196ce6178f9b26c5%3A0xdc6d3b3220ac6b46!2sHoneydew%20Kitwe!5e0!3m2!1sen!2szm!4v1724051205469!5m2!1sen!2szm', '0973006980', 'Honeydew Restaurant, Copperbelt, Zambia', '', NULL, '[\"Dining\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (9, 'cb', 'images/sites/cb/copperclub/1.jpg', 'COPPERCLUB', 'Restaurant', 'Copperclub Restaurant offers a blend of modern and classic cuisine in a stylish setting, making it a great choice for both business lunches and romantic dinners.', 'Copperclub Restaurant is a stylish dining venue located in the Copperbelt region, known for its blend of modern and classic cuisine. The menu at Copperclub features a variety of dishes that cater to different palates, including both local Zambian flavors and international classics. The restaurant\'s chic decor and elegant ambiance make it a popular choice for business lunches, romantic dinners, and special celebrations. Copperclub also boasts an extensive wine list and a range of signature cocktails, making it a great spot for a sophisticated night out. The attentive service and top-notch culinary offerings ensure that every visit to Copperclub is a memorable one.', 'images/sites/cb/copperclub/2.jpg', 'images/sites/cb/copperclub/3.jpg', 'images/sites/cb/copperclub/4.jpg', 'images/sites/cb/copperclub/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3890.531277871203!2d28.2139594!3d-12.808908299999999!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x196ce7cd9cba0fdd%3A0x3785fc5fea69d1c6!2sCopper%20Club%20Restaurant!5e0!3m2!1sen!2szm!4v1724051312837!5m2!1sen!2szm', '0973006990', 'Corner Independence &, Freetown Rd, Kitwe', '', NULL, '[\"Dining\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (10, 'cb', 'images/sites/cb/leos/1.jpg', 'LEO\'S', 'Pub & Grill', 'Leo\'s Pub and Grill is the go-to spot for a lively evening with great pub food and a wide selection of drinks, featuring a friendly atmosphere and live entertainment.', 'Leo\'s Pub & Grill, located in the Copperbelt, is a vibrant and popular venue for those looking to enjoy a lively evening with friends or family. The pub offers a wide selection of drinks, including local beers, international spirits, and classic cocktails, while the grill serves up hearty pub favorites like burgers, steaks, and ribs. Leo\'s is known for its warm and friendly atmosphere, with live entertainment and events regularly on the schedule. Whether you\'re stopping by for a quick drink after work or spending the evening enjoying the live music, Leo\'s Pub & Grill is the perfect place to relax and unwind.', 'images/sites/cb/leos/2.jpg', 'images/sites/cb/leos/3.jpg', 'images/sites/cb/leos/4.jpg', 'images/sites/cb/leos/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3890.408305986271!2d28.208523099999983!3d-12.816871299999992!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x196ce93d6558cda7%3A0x77f0eaa74b508f07!2sLEO%E2%80%99S%20PUB%20AND%20GRILL%20RESTAURANT!5e0!3m2!1sen!2szm!4v1724051382192!5m2!1sen!2szm', '0973007000', 'Enos Chomba Ave, Kitwe', '', NULL, '[\"Dining\",\"Drinks\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (11, 's', 'images/sites/southern/BatokaGorge/1.jpg', 'Batoka Gorge', 'Luxury Bush Lodge', 'Batoka Gorge Lodge offers a unique blend of luxury and nature, perched on the edge of the stunning Batoka Gorge, overlooking the Zambezi River near Victoria Falls.', 'Batoka Gorge Lodge, located near the world-famous Victoria Falls in Zimbabwe, provides an extraordinary experience combining luxury and adventure. The lodge is nestled in lush indigenous gardens with breathtaking views of the Zambezi River. Accommodation options include thatched chalets and tented suites, each with a private veranda. The lodge offers various activities, such as guided wildlife tours, cultural experiences, and adrenaline-packed adventures like bungee jumping and white-water rafting. Visitors can also immerse themselves in the local culture through village visits and cultural performances. The lodge is committed to sustainability, with a portion of its revenues supporting local communities through improvements to schools, water supplies, and clinics.', 'images/sites/southern/BatokaGorge/2.jpg', 'images/sites/southern/BatokaGorge/3.jpg', 'images/sites/southern/BatokaGorge/4.jpg', 'images/sites/southern/BatokaGorge/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3845.9928328680903!2d28.35024877512263!3d-15.430938185159837!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19408c5f03b581fd%3A0x9075a2ae8c008254!2s37d%20Gallery!5e0!3m2!1sen!2szm!4v1724032475727!5m2!1sen!2szm', '+263 83 284 3368', 'Near Victoria Falls, Batoka Gorge, Zimbabwe', 'https://batokaafrica.com', NULL, '[\"Stays\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (12, 's', 'images/sites/southern/vfw/1.jpg', 'Victoria Falls Waterfront', 'Restaurant', 'The Victoria Falls Waterfront Restaurant in Livingstone offers stunning views of the Zambezi River and a relaxed dining experience with a variety of local and international dishes.', 'The Victoria Falls Waterfront Restaurant, located in Livingstone, Zambia, provides a unique dining experience right on the banks of the Zambezi River. The restaurant is part of the Victoria Falls Waterfront lodge, which caters to both budget and luxury travelers. Known for its serene atmosphere, it is a popular spot for both locals and tourists to enjoy a meal while watching the sunset over the river. The menu includes a range of options from local Zambian cuisine to international dishes, making it a versatile choice for all visitors. The restaurant also offers a selection of drinks and is particularly famous for its pizza. In addition to its dining facilities, the Victoria Falls Waterfront is also known for its convenient location, just a short distance from the iconic Victoria Falls, and for offering various activities such as river cruises, fishing, and wildlife safaris.', 'images/sites/southern/vfw/2.jpg', 'images/sites/southern/vfw/3.jpg', 'images/sites/southern/vfw/4.jpg', 'images/sites/southern/vfw/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3847.243217298234!2d25.84225427512194!3d-17.859734185168187!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19408c5f03b581fd%3A0x5fbd7ffceb0066b6!2sVictoria%20Falls%20Waterfront!5e0!3m2!1sen!2szm!4v1724032475727!5m2!1sen!2szm', '+260 213 320 606', 'Livingstone, Zambia', 'https://safpar.com/lodges/victoria-falls-waterfront/', NULL, '[\"Dining\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (13, 's', 'images/sites/southern/ClassicFoodPalace/1.jpg', 'Classic Food Palace', 'Restaurant', 'Classic Food Palace in southern is a popular eatery known for its local cuisine and comfortable atmosphere, offering a variety of dishes that appeal to both locals and visitors.', 'Located in southern, Classic Food Palace is a well-known restaurant that serves a mix of local and international dishes. It is a favored spot for those seeking a cozy dining experience with a taste of Southern Province\'s culinary offerings. The restaurant\'s menu includes traditional Zambian meals alongside other popular options, making it a versatile choice for different palates. Whether you\'re looking for a quick bite or a full meal, Classic Food Palace provides a welcoming environment with prompt service.', 'images/sites/southern/ClassicFoodPalace/2.jpg', 'images/sites/southern/ClassicFoodPalace/3.jpg', 'images/sites/southern/ClassicFoodPalace/4.jpg', 'images/sites/southern/ClassicFoodPalace/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3847.2392384221834!2d26.99021647512198!3d-16.796054885011698!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x192278cb90d45341%3A0x3e4f8e8bcf073b11!2sClassic%20Food%20Palace!5e0!3m2!1sen!2szm!4v1724032475727!5m2!1sen!2szm', '0779910781', 'Choma, Southern Province', 'https://classicfoodpalace.com', NULL, '[\"Dining\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (14, 's', 'images/sites/southern/youngparkchill/1.jpg', 'Young\'s Park and Chill', 'Restaurant & Entertainment', 'Young\'s Park and Chill in Mazabuka is a vibrant spot offering a mix of dining, entertainment, and relaxation, catering to locals and visitors alike.', 'Young\'s Park and Chill is a popular destination in Mazabuka, Southern Province, known for its lively atmosphere and diverse offerings. The venue combines a restaurant, bar, and entertainment area, making it a perfect spot for a night out or a relaxing day with friends and family. The menu features a variety of dishes, with a focus on local flavors and international favorites. Regular events, such as live music and themed parties, add to the vibrant ambiance, making it a go-to spot for both locals and tourists.', 'images/sites/southern/youngparkchill/2.jpg', 'images/sites/southern/youngparkchill/3.jpg', 'images/sites/southern/youngparkchill/4.jpg', 'images/sites/southern/youngparkchill/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3850.391726801166!2d27.74421877511978!3d-15.860614285219614!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19426a9e1555edb9%3A0x9c5e43971fb49f99!2sYoung\'s%20Park%20and%20Chill!5e0!3m2!1sen!2szm!4v1724032475727!5m2!1sen!2szm', '0977xxxxxx', 'Mazabuka, Southern Province', 'https://youngsparkandchill.com', NULL, '[\"Dining\",\"Entertainment\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (15, 's', 'images/sites/southern/elephantcafe/1.jpg', 'Elephant Café', 'Fine Dining & Wildlife Experience', 'Elephant Café in Livingstone offers a unique dining experience combining gourmet cuisine with an intimate encounter with rescued elephants along the Zambezi River.', 'Nestled along the Zambezi River, Elephant Café provides an unforgettable experience that blends fine dining with wildlife interaction. The café is known for its gourmet dishes crafted from locally sourced ingredients, offering a taste of Zambia’s culinary heritage. What sets Elephant Café apart is the opportunity to meet and interact with a herd of rescued elephants, creating a memorable and meaningful connection with nature. This award-winning destination is perfect for those seeking a luxurious and immersive experience in the heart of Africa.', 'images/sites/southern/elephantcafe/2.jpg', 'images/sites/southern/elephantcafe/3.jpg', 'images/sites/southern/elephantcafe/4.jpg', 'images/sites/southern/elephantcafe/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3852.8707294125033!2d25.87150477511855!3d-17.824721285316125!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1947a78820f9cf5b%3A0x32c8af27b8b2b33!2sThe%20Elephant%20Cafe%20Livingstone!5e0!3m2!1sen!2szm!4v1724032475727!5m2!1sen!2szm', '0213320094', 'Zambezi River, Livingstone, Zambia', 'https://elephant.cafe', NULL, '[\"Dining\",\"Wildlife\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (16, 'c', 'images/sites/central/CafeChoconilla/1.jpg', 'Café Choconilla', 'Dessert & Coffee Spot', 'Café Choconilla in central is a delightful café offering a range of desserts, coffee, and light meals, perfect for casual meetups and sweet indulgences.', 'Café Choconilla in central provides a cozy and inviting atmosphere, making it a popular spot for locals and visitors alike. Known for its delicious desserts and quality coffee, the café offers a relaxing space to enjoy a sweet treat or a light meal. Whether you\'re looking for a place to catch up with friends or simply unwind, Café Choconilla is the perfect destination.', 'images/sites/central/CafeChoconilla/2.jpg', 'images/sites/central/CafeChoconilla/3.jpg', 'images/sites/central/CafeChoconilla/4.jpg', 'images/sites/central/CafeChoconilla/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3857.439889732075!2d28.433296075111663!3d-14.440088885244803!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x193eacfdcf25f445%3A0x6b02e54a10a65f3c!2sCafe%20Choconilla%20Kabwe!5e0!3m2!1sen!2szm!4v1724032475727!5m2!1sen!2szm', '0962345678', 'Plot 1501, Freedom Avenue, Kabwe, Zambia', 'https://cafechoconilla.com', NULL, '[\"Coffee & dessert\"]');
