INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (29, 'n', 'images/sites/northern/mikembuzi/1.jpg', 'Mike Mbuzi', 'Local Delicacies & Grill', 'Mike Mbuzi in Lusaka is a popular spot for enjoying local Zambian dishes, particularly known for its expertly grilled meats.', 'Mike Mbuzi offers a vibrant atmosphere where locals and visitors can savor traditional Zambian cuisine with a focus on grilled meats, including the famous \'mbuzi\' (goat). The eatery is known for its flavorful dishes, welcoming ambiance, and commitment to quality. It\'s an ideal place for food lovers seeking an authentic Zambian dining experience.', 'images/sites/northern/mikembuzi/2.jpg', 'images/sites/northern/mikembuzi/3.jpg', 'images/sites/northern/mikembuzi/4.jpg', 'images/sites/northern/mikembuzi/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3844.6463150646446!2d28.322289775170034!3d-15.503445285097046!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19409316ebb9f9df%3A0xcef190914f637102!2sMike%20Mbuzi!5e0!3m2!1sen!2szm!4v1724111520547!5m2!1sen!2szm', '0967654321', 'Plot 56, Mbuzi Street, Lusaka, Zambia', 'https://mikembuzi.com', NULL, '[\"Dining\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (30, 'n', 'images/sites/northern/druskichickenspot/1.jpg', 'Druski Chicken Spot', 'Best Chicken in Town', 'Druski Chicken Spot in Kasama is renowned for its delicious, crispy fried chicken, making it a favorite among locals and visitors alike.', 'Druski Chicken Spot is the go-to place for fried chicken lovers in Kasama. Known for its flavorful and juicy chicken, the spot offers a casual dining experience with a menu that satisfies cravings for comfort food. Whether you\'re grabbing a quick bite or dining in, Druski Chicken Spot delivers on taste and quality.', 'images/sites/northern/druskichickenspot/2.jpg', 'images/sites/northern/druskichickenspot/3.jpg', 'images/sites/northern/druskichickenspot/4.jpg', 'images/sites/northern/druskichickenspot/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3926.6690918556887!2d31.185851475080746!3d-10.207504589908726!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1908c7001b74c823%3A0x83f4e8f96b776524!2sDruski%20Chicken%20Spot!5e0!3m2!1sen!2szm!4v1724111899445!5m2!1sen!2szm', '0978765432', 'Plot 23, Chicken Avenue, Kasama, Zambia', 'https://druskichickenspot.com', NULL, '[\"Dining\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (31, 'l', 'images/sites/luapula/samfyawaterfrontlodge/1.jpg', 'Samfya', 'Waterfront Lodge', 'Samfya Waterfront Lodge offers a serene retreat on the shores of Lake Bangweulu, providing guests with beautiful views and a relaxing atmosphere.', 'Samfya Waterfront Lodge is a popular destination for those looking to enjoy the natural beauty of Lake Bangweulu. The lodge features comfortable accommodations, a restaurant serving delicious local and international cuisine, and various activities like fishing and boat tours. It\'s an ideal spot for both relaxation and adventure.', 'images/sites/luapula/samfyawaterfrontlodge/2.jpg', 'images/sites/luapula/samfyawaterfrontlodge/3.jpg', 'images/sites/luapula/samfyawaterfrontlodge/4.jpg', 'images/sites/luapula/samfyawaterfrontlodge/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3911.4588194664516!2d29.561514075097406!3d-11.37418438881324!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x190da50f3c0d2f49%3A0x3b060a2a20fe9839!2sSamfya%20Water%20front%20Lodge!5e0!3m2!1sen!2szm!4v1724112985904!5m2!1sen!2szm', '0978123456', 'Plot 5, Beach Road, Samfya, Zambia', 'https://samfyawaterfrontlodge.com', NULL, '[\"Stays\"]');
