INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (33, 'l', 'images/sites/luapula/bangweulubeachfrontvillage/1.jpg', 'Bangweulu Beachfront Village', 'Charming Lakeside Getaway', 'Bangweulu Beachfront Village offers a peaceful and picturesque retreat by the shores of Lake Bangweulu, ideal for relaxing vacations.', 'Bangweulu Beachfront Village is a charming and tranquil destination located on the stunning shores of Lake Bangweulu. The village offers comfortable accommodations, a friendly atmosphere, and easy access to the lake for activities such as swimming, boating, and birdwatching. It\'s an excellent choice for those looking to escape the hustle and bustle and enjoy nature\'s beauty.', 'images/sites/luapula/bangweulubeachfrontvillage/2.jpg', 'images/sites/luapula/bangweulubeachfrontvillage/3.jpg', 'images/sites/luapula/bangweulubeachfrontvillage/4.jpg', 'images/sites/luapula/bangweulubeachfrontvillage/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3911.802408917791!2d29.555885075096974!3d-11.349138288836572!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x190da5da31e02927%3A0xe0e3d447033ce8f7!2sBangweulu%20Beachfront%20Village!5e0!3m2!1sen!2szm!4v1724113865965!5m2!1sen!2szm', '0976543210', 'Plot 9, Lakeside Drive, Samfya, Zambia', 'https://bangweulubeachfrontvillage.com', NULL, '[]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (34, 'l', 'images/sites/luapula/vicsgrillhouse/1.jpg', 'VIC\'s GRILL HOUSE', 'Airport Grill and Dine', 'VIC\'s GRILL HOUSE offers a vibrant atmosphere with a focus on grilled specialties and a variety of mouth-watering dishes.', 'VIC\'s GRILL HOUSE is a popular dining spot located near the airport, known for its expertly grilled meats and diverse menu. The restaurant provides a lively setting with both indoor and outdoor seating, perfect for casual dining or special occasions. Guests can enjoy a range of delicious options, from juicy steaks to flavorful burgers, in a welcoming environment.', 'images/sites/luapula/vicsgrillhouse/2.jpg', 'images/sites/luapula/vicsgrillhouse/3.jpg', 'images/sites/luapula/vicsgrillhouse/4.jpg', 'images/sites/luapula/vicsgrillhouse/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3911.7920090951475!2d28.76386587509695!3d-11.34989718883588!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x190d2ffd6eb32857%3A0xa51e4eac73e6f356!2sVIC&#39;s%20GRILL%20HOUSE%20-%20Airport!5e0!3m2!1sen!2szm!4v1724114015850!5m2!1sen!2szm', '0978765432', 'Plot 10, Airport Road, Samfya, Zambia', 'https://vicsgrillhouse.com', NULL, '[\"Dining\"]');
