INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (41, 'nw', 'images/sites/northwestern/spicevalley/1.jpg', 'Spice Valley Bar & Restaurant', 'Dining and Drinks Spot', 'Spice Valley Bar & Restaurant offers a vibrant atmosphere with a diverse menu and a great selection of drinks.', 'Located in the heart of Northwestern Province, Spice Valley Bar & Restaurant is a popular destination for dining and socializing. The establishment boasts a diverse menu featuring local and international dishes, complemented by a well-stocked bar. It\'s an ideal spot for enjoying a meal with friends or unwinding after a busy day.', 'images/sites/northwestern/spicevalley/2.jpg', 'images/sites/northwestern/spicevalley/3.jpg', 'images/sites/northwestern/spicevalley/4.jpg', 'images/sites/northwestern/spicevalley/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3900.1271567781314!2d26.42505767510972!3d-12.171745188074949!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1971d5ecf08fc499%3A0xaad78f697d54cd58!2sSpice%20Valley%20Bar%20%26%20Restaurant!5e0!3m2!1sen!2szm!4v1724116432655!5m2!1sen!2szm', '0976543210', 'Plot 5, Main Road, Solwezi, Northwestern Province, Zambia', 'https://spicevalleyzambia.com', NULL, '[\"Dining\",\"Drinks\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (42, 'nw', 'images/sites/northwestern/buffalowings/1.jpg', 'Buffalo Wings', 'Casual Dining and Sports Bar', 'Buffalo Wings offers a relaxed environment with a focus on delicious wings and a range of casual dining options.', 'Buffalo Wings is a popular spot in Northwestern Province, known for its tasty chicken wings and casual dining atmosphere. The restaurant also features sports screenings, making it a great place to enjoy a meal while catching up on your favorite games. With a menu that caters to various tastes, Buffalo Wings is ideal for both family outings and casual hangouts with friends.', 'images/sites/northwestern/buffalowings/2.jpg', 'images/sites/northwestern/buffalowings/3.jpg', 'images/sites/northwestern/buffalowings/4.jpg', 'images/sites/northwestern/buffalowings/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d62410.37174611888!2d26.38284978202179!3d-12.136203505404943!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x196e2b8faf3de8cd%3A0xd7d5e8d41283bc00!2sBuffalo%20Wings!5e0!3m2!1sen!2szm!4v1724116580127!5m2!1sen!2szm', '0978675309', 'Plot 10, Main Street, Solwezi, Northwestern Province, Zambia', 'https://buffalowingszambia.com', NULL, '[\"Dining\",\"Drinks\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (43, 'nw', 'images/sites/northwestern/kozalodge/1.jpg', 'Koza Lodge and Restaurant', 'Lodge & Dining Experience', 'Koza Lodge and Restaurant combines comfortable lodging with a variety of dining options, offering a pleasant stay and delicious meals.', 'Koza Lodge and Restaurant is a versatile destination in Northwestern Province, providing both accommodation and dining services. The lodge features cozy rooms and an on-site restaurant that serves a range of meals. Guests can enjoy a relaxing stay while sampling local and international dishes. It\'s an ideal choice for travelers seeking comfort and good food.', 'images/sites/northwestern/kozalodge/2.jpg', 'images/sites/northwestern/kozalodge/3.jpg', 'images/sites/northwestern/kozalodge/4.jpg', 'images/sites/northwestern/kozalodge/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3899.866566115675!2d26.419389975109986!3d-12.189481288058653!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x196e2ab4816661cf%3A0xe102d0f5013f8e94!2sKoza%20Lodge%20and%20restaurant!5e0!3m2!1sen!2szm!4v1724116720116!5m2!1sen!2szm', '0978556710', 'Plot 22, Koza Road, Solwezi, Northwestern Province, Zambia', 'https://kozalodgerestaurantzambia.com', NULL, '[\"Dining\",\"Stays\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (44, 'nw', 'images/sites/northwestern/leosbarrestaurant/1.jpg', 'Leo\'s Pub & Grill', 'Bar & Restaurant', 'Leo\'s Bar and Restaurant in Solwezi is a vibrant spot offering a lively atmosphere with a variety of drinks and a diverse menu of dishes.', 'Leo\'s Bar and Restaurant Solwezi is known for its welcoming ambiance and extensive menu that caters to various tastes. Whether you\'re looking for a place to relax with friends or enjoy a hearty meal, this establishment provides a comfortable setting. The bar serves a range of beverages, while the restaurant offers both local and international cuisine.', 'images/sites/northwestern/leosbarrestaurant/2.jpg', 'images/sites/northwestern/leosbarrestaurant/3.jpg', 'images/sites/northwestern/leosbarrestaurant/4.jpg', 'images/sites/northwestern/leosbarrestaurant/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d31198.93262022731!2d26.40136526319259!3d-12.189480511851077!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1971d51dcbed8f0b%3A0x20d5dc4956ba766b!2sLeo&#39;s%20Bar%20and%20Restaurant%20Solwezi!5e0!3m2!1sen!2szm!4v1724116942150!5m2!1sen!2szm', '0956327890', 'Plot 8, Lusaka Road, Solwezi, Northwestern Province, Zambia', 'https://leosbarsolwezi.com', NULL, '[\"Dining\",\"Drinks\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (45, 'nw', 'images/sites/northwestern/kansanshiclubhouse/1.jpg', 'Kansanshi Club House', 'Club House', 'Kansanshi Club House in Solwezi is a popular venue known for its social atmosphere and recreational facilities. It provides a variety of entertainment options for locals and visitors alike.', 'Kansanshi Club House is a well-known spot for social gatherings and recreational activities. With its range of facilities and lively environment, it\'s a favorite among both locals and travelers looking for a place to unwind and enjoy themselves. The club offers various amenities including sports facilities, dining options, and event spaces.', 'images/sites/northwestern/kansanshiclubhouse/2.jpg', 'images/sites/northwestern/kansanshiclubhouse/3.jpg', 'images/sites/northwestern/kansanshiclubhouse/4.jpg', 'images/sites/northwestern/kansanshiclubhouse/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3900.2032838189602!2d26.414332275109548!3d-12.166559088079726!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19702b07bdca95e7%3A0x46a22a54564b8272!2sKansanshi%20Club%20House!5e0!3m2!1sen!2szm!4v1724117122468!5m2!1sen!2szm', '0954321987', 'Kansanshi Road, Solwezi, Northwestern Province, Zambia', 'https://kansanshiclubhouse.com', NULL, '[]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (46, 'm', 'images/sites/muchinga/crumachlodge/1.jpg', 'Crumach Lodge', 'Lodge', 'Crumach Lodge offers a serene escape in the heart of Muchinga Province, providing a peaceful retreat with comfortable accommodations and beautiful natural surroundings.', 'Crumach Lodge is known for its tranquil environment and excellent service. The lodge features cozy rooms, beautiful views, and a range of amenities to ensure a relaxing stay. It is a great choice for visitors looking to experience the natural beauty of Muchinga Province while enjoying modern comforts.', 'images/sites/muchinga/crumachlodge/2.jpg', 'images/sites/muchinga/crumachlodge/3.jpg', 'images/sites/muchinga/crumachlodge/4.jpg', 'images/sites/muchinga/crumachlodge/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3904.789951233245!2d31.437870075104534!3d-11.849971588371723!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19101169fcfae5bb%3A0xd9da939f98c8f231!2sCrumach%20Lodge!5e0!3m2!1sen!2szm!4v1724117774811!5m2!1sen!2szm', '0976543210', 'Crumach Lodge Road, Muchinga Province, Zambia', 'https://crumachlodge.com', NULL, '[\"Stays\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (47, 'm', 'images/sites/muchinga/bayamaslodge/1.jpg', 'Bayama\'s Lodge', 'Lodge', 'Bayama\'s Lodge offers a welcoming and comfortable stay in Muchinga Province. With its serene atmosphere and excellent facilities, it\'s a great choice for travelers seeking relaxation and a touch of luxury.', 'Bayama\'s Lodge provides guests with a tranquil setting and modern amenities. It features well-appointed rooms, scenic views, and a friendly atmosphere, making it an ideal destination for both business and leisure travelers.', 'images/sites/muchinga/bayamaslodge/2.jpg', 'images/sites/muchinga/bayamaslodge/3.jpg', 'images/sites/muchinga/bayamaslodge/4.jpg', 'images/sites/muchinga/bayamaslodge/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3904.8549850518048!2d31.44373477510454!3d-11.845422788375922!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19100e029a7dd583%3A0x1f8a3c9663019a7d!2sBayama&#39;s%20Lodge!5e0!3m2!1sen!2szm!4v1724117967112!5m2!1sen!2szm', '0987654321', 'Bayama\'s Lodge Road, Muchinga Province, Zambia', 'https://bayamaslodge.com', NULL, '[\"Stays\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (48, 'm', 'images/sites/muchinga/kwasurestaurant/1.jpg', 'Kwasu Restaurant And Cocktail Bar', 'Restaurant & Bar', 'Kwasu Restaurant and Cocktail Bar is a popular dining spot offering a diverse menu and a vibrant cocktail selection. Ideal for both casual and special occasions, it provides a lively atmosphere and quality service.', 'Enjoy a variety of dishes and expertly crafted cocktails at Kwasu Restaurant and Cocktail Bar. With its welcoming environment and excellent service, it’s a great place for dining and socializing in Eastern Province.', 'images/sites/muchinga/kwasurestaurant/2.jpg', 'images/sites/muchinga/kwasurestaurant/3.jpg', 'images/sites/muchinga/kwasurestaurant/4.jpg', 'images/sites/muchinga/kwasurestaurant/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3913.600558352613!2d33.151466379655254!3d-11.217161260492922!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x190359e744b104bd%3A0x8a9cf2b423e1121b!2sKwasu%20Restaurant%20And%20Cocktail%20Bar!5e0!3m2!1sen!2szm!4v1724118251636!5m2!1sen!2szm', '0976543210', '123 Cocktail Street, muchinga Province, Zambia', 'https://kwasurestaurant.com', NULL, '[\"Dining\",\"Drinks\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (49, 'm', 'images/sites/muchinga/woodnliquor/1.jpg', 'Wood n\' Liquor', 'Restaurant & Bar', 'Wood n\' Liquor is a stylish restaurant and bar known for its cozy ambiance and extensive drink menu. It’s a popular spot for both casual gatherings and special occasions.', 'Experience a unique dining and drinking experience at Wood n\' Liquor. The establishment is known for its welcoming atmosphere, diverse menu, and a wide range of liquor options.', 'images/sites/muchinga/woodnliquor/2.jpg', 'images/sites/muchinga/woodnliquor/3.jpg', 'images/sites/muchinga/woodnliquor/4.jpg', 'images/sites/muchinga/woodnliquor/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3913.59235425503!2d33.153817875094944!3d-11.217766888959076!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1903597775767075%3A0xbb134029923f6892!2sWood%20n\'%20Liquor!5e0!3m2!1sen!2szm!4v1724118494896!5m2!1sen!2szm', '0976543211', '456 Liquor Lane, muchinga Province, Zambia', 'https://woodnliquor.com', NULL, '[\"Dining\",\"Drinks\"]');
INSERT INTO `chillspots` (`id`, `ln`, `img`, `h1`, `h2`, `p`, `details`, `img1`, `img2`, `img3`, `img4`, `map`, `phone`, `address`, `site`, `opening_hours`, `activities`) VALUES (50, 'm', 'images/sites/Muchinga/dajoint/1.jpg', 'Da Joint Restaurant', 'Casual Dining', 'Da Joint Restaurant is a popular spot for casual dining in the Muchinga Province. Known for its hearty meals and relaxed atmosphere, it’s a favorite among locals and visitors alike.', 'Enjoy a variety of dishes and a welcoming environment at Da Joint Restaurant. It’s the perfect place for a laid-back meal with friends or family.', 'images/sites/Muchinga/dajoint/2.jpg', 'images/sites/Muchinga/dajoint/3.jpg', 'images/sites/Muchinga/dajoint/4.jpg', 'images/sites/Muchinga/dajoint/5.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3927.358830847739!2d32.63472437507998!3d-10.151459389961788!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19069e9a6affffa9%3A0x453d46fdc184cadd!2sDa%20Joint%20Restaurant!5e0!3m2!1sen!2szm!4v1724118678465!5m2!1sen!2szm', '0987654321', '123 Main Street, Muchinga Province, Zambia', 'https://dajointrestaurant.com', NULL, '[\"Dining\"]');

CREATE TABLE `contact_messages` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `email` varchar(254) NOT NULL,
  `subject` varchar(150) NOT NULL,
  `message` text NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `email_outbox` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `kind` varchar(20) NOT NULL,
  `recipient` varchar(254) NOT NULL,
  `payload` json NOT NULL,
  `subscriber_id` bigint DEFAULT NULL,
  `campaign_id` bigint DEFAULT NULL,
  `status` enum('queued','sending','sent','failed','skipped') NOT NULL DEFAULT 'queued',
  `attempts` int NOT NULL DEFAULT '0',
  `available_at` bigint NOT NULL DEFAULT '0',
  `locked_until` bigint DEFAULT NULL,
  `last_error` varchar(100) DEFAULT NULL,
  `sent_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_campaign_recipient` (`campaign_id`,`subscriber_id`),
  KEY `ix_outbox_ready` (`status`,`available_at`),
  KEY `subscriber_id` (`subscriber_id`),
  CONSTRAINT `email_outbox_ibfk_1` FOREIGN KEY (`subscriber_id`) REFERENCES `newsletter_subscribers` (`id`),
  CONSTRAINT `email_outbox_ibfk_2` FOREIGN KEY (`campaign_id`) REFERENCES `newsletter_campaigns` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `login_limits` (
  `bucket_key` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `attempts` int unsigned NOT NULL,
  `expires` bigint NOT NULL,
  PRIMARY KEY (`bucket_key`),
  KEY `ix_limits_expires` (`expires`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `news` (
  `id` int NOT NULL AUTO_INCREMENT,
  `headline` varchar(255) DEFAULT NULL,
  `news` text,
  `img` varchar(1024) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO `news` (`id`, `headline`, `news`, `img`) VALUES (1, 'Hollywood Star will Smith Explores Zambia\'s Victoria Falls', 'Will Smith experienced Zambia\'s iconic Victoria Falls on March 12, 2023, sharing his adventure on social media, boosting the country’s appeal to global travelers.', 'images/news/1.jpg');
INSERT INTO `news` (`id`, `headline`, `news`, `img`) VALUES (2, 'New Luxury Safari Lodge Opens in Lower Zambezi National Park', 'The new lodge opened on September 5, 2022, offering unparalleled wildlife experiences and luxurious accommodations, enhancing Zambia’s status as a top African safari destination.', 'images/news/2.jpg');
INSERT INTO `news` (`id`, `headline`, `news`, `img`) VALUES (3, 'Zambia\'s Liuwa Plain National Park Attracts International Wildlife Photographers', 'Liuwa Plain’s stunning landscapes and rich biodiversity drew photographers worldwide on November 18, 2021, highlighting Zambia\'s untouched natural beauty and wildlife.', 'images/news/3.jpg');
INSERT INTO `news` (`id`, `headline`, `news`, `img`) VALUES (4, 'British Royals Prince William and Kate Middleton Enjoy Wildlife Safari in South Luangwa', 'The royal couple’s visit to South Luangwa National Park on September 27, 2018, emphasized Zambia’s pristine wilderness and its growing reputation for exclusive safaris.', 'images/news/4.jpg');
INSERT INTO `news` (`id`, `headline`, `news`, `img`) VALUES (5, 'Zambia Launches Ecotourism Initiative to Promote Sustainable Travel in National Parks', 'Launched on April 10, 2023, Zambia’s ecotourism drive aims to balance wildlife conservation with sustainable travel, offering eco-conscious tourists meaningful experiences in nature.', 'images/news/5.jpg');
INSERT INTO `news` (`id`, `headline`, `news`, `img`) VALUES (6, 'New Adventure Park in Lusaka Set to Boost Domestic Tourism', 'Lusaka’s new adventure park opened on July 21, 2023, providing thrilling activities for all ages, encouraging more locals and tourists to explore Zambia’s capital.', 'images/news/6.jpg');
INSERT INTO `news` (`id`, `headline`, `news`, `img`) VALUES (7, 'Angelina Jolie Advocates for Wildlife Conservation During Visit to Kafue National Park', 'Angelina Jolie\'s conservation efforts in Kafue National Park on November 8, 2017, spotlight Zambia’s wildlife protection initiatives, inspiring global support for endangered species.', 'images/news/7.jpg');
INSERT INTO `news` (`id`, `headline`, `news`, `img`) VALUES (8, 'Zambia Introduces Cultural Heritage Trails to Showcase Traditional Villages and Local Artisans', 'Introduced on February 14, 2024, Zambia’s new cultural trails offer tourists authentic experiences, celebrating traditional crafts and village life, and preserving local heritage.', 'images/news/8.jpg');

CREATE TABLE `newsletter_campaigns` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `subject` varchar(150) NOT NULL,
  `body` text NOT NULL,
  `status` enum('draft','queued') NOT NULL DEFAULT 'draft',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `newsletter_subscribers` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `email` varchar(254) NOT NULL,
  `status` enum('pending','active','unsubscribed') NOT NULL DEFAULT 'pending',
  `confirm_hash` char(64) DEFAULT NULL,
  `confirm_expires` bigint DEFAULT NULL,
  `unsubscribe_token` char(64) NOT NULL,
  `requested_at` bigint NOT NULL,
  `confirmed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `uq_unsubscribe_token` (`unsubscribe_token`),
  KEY `ix_subscriber_status` (`status`),
  KEY `ix_confirm_hash` (`confirm_hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `review` (
  `userId` int NOT NULL,
  `locationId` bigint NOT NULL,
  `rating` float NOT NULL,
  `comment` text NOT NULL,
  UNIQUE KEY `uq_review_user_location` (`userId`,`locationId`),
  KEY `fk_review_location` (`locationId`),
  CONSTRAINT `fk_review_location` FOREIGN KEY (`locationId`) REFERENCES `chillspots` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_review_user` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_review_rating` CHECK (((`rating` >= 1) and (`rating` <= 5)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO `review` (`userId`, `locationId`, `rating`, `comment`) VALUES (1, 1, 3.5, 'decent\n');
